import React from "react";
import withNavigation from "../utils/withNavigation";
import LeftSlidebar from "./leftSlidebar";
import axiosInstance from "../configurations/instance";

class EventsList extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      events: [],
      selectedEvent: null,
      editEvent: null,
      errorMessage: "",
    };
  }

  componentDidMount() {
    axiosInstance
      .get("/event/all-events")
      .then((response) => {
        this.setState({ events: response.data });
      })
      .catch((error) => console.error("Ошибка при загрузке событий:", error));
  }

  handleView = (id) => {
    axiosInstance
      .get(`/event/${id}`)
      .then((response) => {
        this.setState({ selectedEvent: response.data, editEvent: null });
      })
      .catch((error) => console.error("Ошибка при загрузке события:", error));
  };

  handleEdit = (id) => {
    axiosInstance
      .get(`/event/${id}`)
      .then((response) => {
        this.setState({ editEvent: response.data, selectedEvent: null });
      })
      .catch((error) => console.error("Ошибка при загрузке события:", error));
  };

  handleDelete = (id) => {
    axiosInstance
      .delete(`/event/${id}`)
      .then(() => {
        this.setState((prevState) => ({
          events: prevState.events.filter((event) => event.eventId !== id),
          selectedEvent: null,
          editEvent: null,
        }));
      })
      .catch((error) => console.error("Ошибка при удалении события:", error));
  };

  addEmailField = () => {
    this.setState((prevState) => ({
      editEvent: {
        ...prevState.editEvent,
        emailFields: [...prevState.editEvent.emailFields, ""],
      },
    }));
  };

  removeEmailField = (index) => {
    if (index > 0) {
      this.setState((prevState) => ({
        editEvent: {
          ...prevState.editEvent,
          emailFields: prevState.editEvent.emailFields.filter((_, i) => i !== index),
        },
      }));
    }
  };

  addParticipant = () => {
    this.setState((prevState) => ({
      editEvent: {
        ...prevState.editEvent,
        participants: [...prevState.editEvent.participants, { name: "", iin: "" }],
      },
    }));
  };

  removeParticipant = (index) => {
    if (index > 0) {
      this.setState((prevState) => ({
        editEvent: {
          ...prevState.editEvent,
          participants: prevState.editEvent.participants.filter((_, i) => i !== index),
        },
      }));
    }
  };

  handleInputChange = (field, value) => {
    this.setState((prevState) => ({
      editEvent: {
        ...prevState.editEvent,
        [field]: value,
      },
    }));
  };

  handleEmailChange = (index, value) => {
    const updatedEmails = [...this.state.editEvent.emailFields];
    updatedEmails[index] = value;
    this.setState((prevState) => ({
      editEvent: {
        ...prevState.editEvent,
        emailFields: updatedEmails,
      },
    }));
  };

  handleParticipantChange = (index, field, value) => {
    const updatedParticipants = [...this.state.editEvent.participants];
    updatedParticipants[index][field] = value;
    this.setState((prevState) => ({
      editEvent: {
        ...prevState.editEvent,
        participants: updatedParticipants,
      },
    }));
  };

  handleUpdate = () => {
    const { eventName, eventType, eventDate, emailFields, participants } =
      this.state.editEvent;

    if (
      !eventName ||
      !eventType ||
      !eventDate ||
      emailFields.some((email) => !email) ||
      participants.some((participant) => !participant.name || !participant.iin)
    ) {
      this.setState({ errorMessage: "Все поля должны быть заполнены" });
      return;
    }

    axiosInstance
      .put(`/event/update-event/${this.state.editEvent.eventId}`, {
        eventName,
        eventType,
        eventDate,
        emailFields,
        participants,
      })
      .then((response) => {
        console.log("Событие обновлено:", response.data);
        this.setState({ editEvent: null, errorMessage: "" });
      })
      .catch((error) => {
        console.error("Ошибка при обновлении события:", error);
      });
  };

  getStatus = (eventDate) => {
    const now = new Date();
    const eventStart = new Date(eventDate);
    const diffInMs = now - eventStart;
    const diffInHours = diffInMs / (1000 * 60 * 60);
  
    if (diffInHours < 0) {
      return "В ожидании";
    } else if (diffInHours <= 12) {
      return "В процессе";
    } else {
      return "Завершено";
    }
  };
  

  render() {
    const { events, selectedEvent, editEvent, errorMessage } = this.state;

    return (
      <div className="creating-page">
        <header className="main-header"></header>
        <div className="profile-page">
          <LeftSlidebar />
          <div className="content">
            <h1>Список событий</h1>
            <table className="event-table">
              <thead>
                <tr>
                  <th>№</th>
                  <th>Название</th>
                  <th>Дата проведения</th>
                  <th>Статус</th>
                  <th>Действия</th>
                </tr>
              </thead>
              <tbody>
                {events.map((event, index) => {
                  const status = this.getStatus(event.eventDate);
                  const statusClass = this.getStatusClass(status);

                  return (
                    <tr key={event.eventId}>
                      <td>{index + 1}</td>
                      <td>{event.eventName}</td>
                      <td>{new Date(event.eventDate).toLocaleDateString()}</td>
                      <td>
                        <span className={`status-badge ${statusClass}`}>{status}</span>
                      </td>
                      <td>
                        <button
                          className="check"
                          onClick={() => this.handleView(event.eventId)}
                        >
                          Просмотр
                        </button>
                        {this.isEditableOrDeletable(event.eventDate) && (
                          <>
                            <button
                              className="change"
                              onClick={() => this.handleEdit(event.eventId)}
                            >
                              Изменить
                            </button>
                            <button
                              className="delete"
                              onClick={() => this.handleDelete(event.eventId)}
                            >
                              Удалить
                            </button>
                          </>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>

            {editEvent && (
              <div className="createForm">
                {errorMessage && (
                  <p style={{ color: "red", fontWeight: "bold" }}>{errorMessage}</p>
                )}
                <h3>Название мероприятия</h3>
                <input
                  type="text"
                  value={editEvent.eventName}
                  onChange={(e) => this.handleInputChange("eventName", e.target.value)}
                />
                <h3>Выберите тип мероприятия</h3>
                <select
                  value={editEvent.eventType}
                  onChange={(e) => this.handleInputChange("eventType", e.target.value)}
                >
                  <option value="" disabled>
                    Выберите тип мероприятия
                  </option>
                  <option value="seminar">Семинар</option>
                  <option value="competition">Соревнования</option>
                  <option value="conference">Конференция</option>
                </select>
                <h3>Дата проведения</h3>
                <input
                  type="datetime-local"
                  value={new Date(editEvent.eventDate).toISOString().slice(0, 16)}
                  onChange={(e) => this.handleInputChange("eventDate", e.target.value)}
                />
                <h3>Добавьте проверяющего(-их)</h3>
                {editEvent.emailFields.map((email, index) => (
                  <div key={index}>
                    <input
                      type="text"
                      value={email}
                      onChange={(e) => this.handleEmailChange(index, e.target.value)}
                    />
                    {index > 0 && (
                      <button
                        type="button"
                        onClick={() => this.removeEmailField(index)}
                      >
                        Удалить
                      </button>
                    )}
                  </div>
                ))}
                <button type="button" onClick={this.addEmailField}>
                  Добавить проверяющего
                </button>
                <h3>Добавьте участника(-ов)</h3>
                {editEvent.participants.map((participant, index) => (
                  <div key={index}>
                    <h4>Участник №{index + 1}</h4>
                    <input
                      type="text"
                      value={participant.name}
                      onChange={(e) =>
                        this.handleParticipantChange(index, "name", e.target.value)
                      }
                    />
                    <input
                      type="text"
                      value={participant.iin}
                      onChange={(e) =>
                        this.handleParticipantChange(index, "iin", e.target.value)
                      }
                    />
                    {index > 0 && (
                      <button
                        type="button"
                        onClick={() => this.removeParticipant(index)}
                      >
                        Удалить
                      </button>
                    )}
                  </div>
                ))}
                <button type="button" onClick={this.addParticipant}>
                  Добавить участника
                </button>
                <button
                  type="button"
                  className="add-button"
                  onClick={this.handleUpdate}
                >
                  Сохранить
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }
}

export default withNavigation(EventsList);
